import {describe, expect, it} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry valid input', () => {
  it('passes Berlin input with extra properties unchanged exactly once @specs/hal-engine-tool-input-validation/spec.md#5', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'weather',
        description: 'Weather forecast',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return JSON.stringify(input);
      }
    );

    const response = await registry.execute('weather', {location: 'Berlin', extra: '0123'});

    expect({received, response}).toEqual({
      received: [{location: 'Berlin', extra: '0123'}],
      response: {result: JSON.stringify({location: 'Berlin', extra: '0123'})},
    });
  });
});
EOF
